import{_ as n}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as p,c as o,f as l,q as s,D as i,Q as t,g as r}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const f=JSON.parse('{"title":"前端 Monorepo 彻底讲清楚","description":"","frontmatter":{},"headers":[],"relativePath":"column/前端进阶/工程化/前端 Monorepo 指南.md","filePath":"column/前端进阶/工程化/前端 Monorepo 指南.md","lastUpdated":1788224557000}'),c={name:"column/前端进阶/工程化/前端 Monorepo 指南.md"};function d(h,a,k,u,b,m){const e=p("ArticleMetadata");return l(),o("div",null,[a[0]||(a[0]=s("h1",{id:"前端-monorepo-彻底讲清楚",tabindex:"-1"},[r("前端 Monorepo 彻底讲清楚 "),s("a",{class:"header-anchor",href:"#前端-monorepo-彻底讲清楚","aria-label":'Permalink to "前端 Monorepo 彻底讲清楚"'},"​")],-1)),i(e),a[1]||(a[1]=t(`<nav class="table-of-contents"><ul><li><a href="#第一章-monorepo-到底是什么">第一章：Monorepo 到底是什么？</a></li><li><a href="#第二章-为什么前端需要-monorepo">第二章：为什么前端需要 Monorepo？</a></li><li><a href="#第三章-workspace-——-让项目真正能互相使用">第三章：Workspace —— 让项目真正能互相使用</a><ul><li><a href="#workspace-是什么">Workspace 是什么？</a></li><li><a href="#关键区别">关键区别</a></li></ul></li><li><a href="#第四章-为什么根目录和子包都要有-package-json">第四章：为什么根目录和子包都要有 package.json？</a><ul><li><a href="#根目录的-package-json-做什么">根目录的 package.json 做什么？</a></li><li><a href="#子包的-package-json-做什么">子包的 package.json 做什么？</a></li><li><a href="#用一个类比理解">用一个类比理解</a></li></ul></li><li><a href="#第五章-子包如何使用根目录的能力">第五章：子包如何使用根目录的能力？</a></li><li><a href="#第六章-完整关系梳理">第六章：完整关系梳理</a></li><li><a href="#第七章-总结">第七章：总结</a></li></ul></nav><p>很多人对 Monorepo 的理解停留在「把多个项目放在一个仓库里」，但对它和 Workspace 的区别、为什么要写那么多 <code>package.json</code>、<code>pnpm-workspace.yaml</code> 到底干什么，仍然容易混淆。</p><blockquote><p><a href="https://github.com/lexmin0412/dify-app-hub" target="_blank" rel="noreferrer">https://github.com/lexmin0412/dify-app-hub</a> 这个项目使用了 Monorepo 进行管理</p></blockquote><p>这篇文章按章节把这些概念彻底拆开讲清楚。</p><h2 id="第一章-monorepo-到底是什么" tabindex="-1">第一章：Monorepo 到底是什么？ <a class="header-anchor" href="#第一章-monorepo-到底是什么" aria-label="Permalink to &quot;第一章：Monorepo 到底是什么？&quot;">​</a></h2><p><strong>Monorepo 不是协议，不是工具，也不是技术标准。</strong></p><p>它只是一种<strong>代码仓库的组织策略</strong>：</p><blockquote><p>把多个相关的项目，放在同一个 Git 仓库里管理。</p></blockquote><p>对应的反面是 Multi-repo（每个项目一个独立仓库）。</p><p>举个例子，你有这些东西：</p><ul><li>一个用户前台（web）</li><li>一个管理后台（admin）</li><li>一套公共组件库（ui）</li><li>一些工具函数（utils）</li></ul><p><strong>Multi-repo 的做法</strong>：四个独立的 Git 仓库。 <strong>Monorepo 的做法</strong>：全部放进同一个仓库。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-frontend/</span></span>
<span class="line"><span>├── apps/</span></span>
<span class="line"><span>│   ├── web/</span></span>
<span class="line"><span>│   └── admin/</span></span>
<span class="line"><span>└── packages/</span></span>
<span class="line"><span>    ├── ui/</span></span>
<span class="line"><span>    └── utils/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>只要代码在同一个仓库里，它就已经是 Monorepo 了。 <strong>到这一步，不需要任何配置文件。</strong></p><h2 id="第二章-为什么前端需要-monorepo" tabindex="-1">第二章：为什么前端需要 Monorepo？ <a class="header-anchor" href="#第二章-为什么前端需要-monorepo" aria-label="Permalink to &quot;第二章：为什么前端需要 Monorepo？&quot;">​</a></h2><p>在多项目场景下，Multi-repo 会遇到这些问题：</p><ul><li>公共组件要先发 npm 包，再在其他项目里升级版本，流程长且容易出版本不一致</li><li>改一个基础库，需要同时改多个仓库、提多个 PR</li><li>依赖版本、ESLint、TypeScript 配置容易各写各的</li><li>跨项目重构成本高</li></ul><p>Monorepo 的核心价值在于：</p><ul><li>共享代码可以直接引用源码，改完立刻生效，不需要发版</li><li>工具链和规范可以统一</li><li>一次改动能覆盖所有相关项目</li><li>CI 和依赖管理更集中</li></ul><p>它解决的是「多个前端项目如何高效协作」的问题。</p><h2 id="第三章-workspace-——-让项目真正能互相使用" tabindex="-1">第三章：Workspace —— 让项目真正能互相使用 <a class="header-anchor" href="#第三章-workspace-——-让项目真正能互相使用" aria-label="Permalink to &quot;第三章：Workspace —— 让项目真正能互相使用&quot;">​</a></h2><p>Monorepo 只解决了「代码放在一起」，但默认情况下，这些项目仍然互相不认识。</p><p>这时候就需要 <strong>Workspace</strong>。</p><h3 id="workspace-是什么" tabindex="-1">Workspace 是什么？ <a class="header-anchor" href="#workspace-是什么" aria-label="Permalink to &quot;Workspace 是什么？&quot;">​</a></h3><p>Workspace 是包管理器（pnpm / yarn / npm）提供的一种机制，用来告诉它：</p><blockquote><p>「这几个文件夹是当前仓库的工作区成员，请把它们当作一个整体来管理，允许互相引用。」</p></blockquote><p>以 pnpm 为例，需要在根目录创建：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># pnpm-workspace.yaml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">packages</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;apps/*&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;packages/*&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>有了这个配置后，你就可以在项目里这样引用：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@myorg/ui&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workspace:*&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>workspace:*</code> 的含义是：去当前仓库的 workspace 里找名为 <code>@myorg/ui</code> 的包，直接使用本地源码，不要去 npm 下载。</p><h3 id="关键区别" tabindex="-1">关键区别 <a class="header-anchor" href="#关键区别" aria-label="Permalink to &quot;关键区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>本质</th><th>是否必须配置文件</th></tr></thead><tbody><tr><td>Monorepo</td><td>把多个项目放进一个仓库</td><td>不需要</td></tr><tr><td>Workspace</td><td>让这些项目能互相引用</td><td>需要（如 pnpm-workspace.yaml）</td></tr></tbody></table><p>没有 Workspace 配置，只是「物理上的 Monorepo」； 有了 Workspace，才是真正能协作的 Monorepo。</p><h2 id="第四章-为什么根目录和子包都要有-package-json" tabindex="-1">第四章：为什么根目录和子包都要有 package.json？ <a class="header-anchor" href="#第四章-为什么根目录和子包都要有-package-json" aria-label="Permalink to &quot;第四章：为什么根目录和子包都要有 package.json？&quot;">​</a></h2><p>这是最容易让人觉得「多此一举」的地方。</p><h3 id="根目录的-package-json-做什么" tabindex="-1">根目录的 package.json 做什么？ <a class="header-anchor" href="#根目录的-package-json-做什么" aria-label="Permalink to &quot;根目录的 package.json 做什么？&quot;">​</a></h3><p>它是整个仓库的<strong>总控中心</strong>，主要负责：</p><ul><li>声明这是一个 workspace</li><li>安装整个仓库共用的开发工具（typescript、eslint、turbo 等）</li><li>定义统一的脚本（<code>dev</code>、<code>build</code>、<code>lint</code>）</li><li>标记 <code>&quot;private&quot;: true</code>，防止被误发布到 npm</li></ul><h3 id="子包的-package-json-做什么" tabindex="-1">子包的 package.json 做什么？ <a class="header-anchor" href="#子包的-package-json-做什么" aria-label="Permalink to &quot;子包的 package.json 做什么？&quot;">​</a></h3><p>每一个 <code>apps/*</code> 或 <code>packages/*</code> 在逻辑上都是一个<strong>独立的包</strong>，必须有自己的身份证，包括：</p><ul><li>名字（<code>@myorg/ui</code>、<code>@myorg/web</code>）—— 别人才能引用它</li><li>自己的依赖</li><li>自己的启动/构建脚本</li><li>入口文件（<code>main</code>、<code>exports</code>、<code>types</code>）</li><li>版本号（以后如果要单独发 npm 包）</li></ul><p>如果 <code>packages/ui</code> 没有自己的 <code>package.json</code>，它就没有名字，其他包就无法通过 <code>@myorg/ui</code> 引用它。</p><h3 id="用一个类比理解" tabindex="-1">用一个类比理解 <a class="header-anchor" href="#用一个类比理解" aria-label="Permalink to &quot;用一个类比理解&quot;">​</a></h3><ul><li>根目录的 <code>package.json</code> = 公司总部（制定制度、提供公共工具）</li><li>子包的 <code>package.json</code> = 每个部门自己的营业执照和职责说明</li></ul><p>总部有制度，不代表下面部门可以没有自己的身份。两者职责不同，不能互相替代。</p><h2 id="第五章-子包如何使用根目录的能力" tabindex="-1">第五章：子包如何使用根目录的能力？ <a class="header-anchor" href="#第五章-子包如何使用根目录的能力" aria-label="Permalink to &quot;第五章：子包如何使用根目录的能力？&quot;">​</a></h2><p>子包<strong>不需要、也不能</strong>把根目录的 <code>package.json</code> 当作依赖来安装。</p><p>它们之间是「管理与被管理」的关系，而不是普通的依赖关系。</p><p>当你在根目录执行 <code>pnpm install</code> 时，包管理器会：</p><ol><li>读取 <code>pnpm-workspace.yaml</code>，识别所有子包</li><li>把根目录的 <code>devDependencies</code>（如 typescript）提升到整个仓库可用</li><li>处理子包之间通过 <code>workspace:*</code> 产生的本地引用</li></ol><p>因此：</p><ul><li>子包可以直接使用根目录安装的工具</li><li>在根目录执行统一脚本，可以驱动所有子包</li><li>子包只需要声明自己依赖哪些<strong>其他子包</strong></li></ul><h2 id="第六章-完整关系梳理" tabindex="-1">第六章：完整关系梳理 <a class="header-anchor" href="#第六章-完整关系梳理" aria-label="Permalink to &quot;第六章：完整关系梳理&quot;">​</a></h2><p>用一张表把所有概念放在一起：</p><table tabindex="0"><thead><tr><th>概念</th><th>它是什么</th><th>核心作用</th><th>必须配置吗？</th></tr></thead><tbody><tr><td>Monorepo</td><td>代码组织策略</td><td>多个项目放在同一个仓库</td><td>不需要</td></tr><tr><td>Workspace</td><td>包管理器提供的机制</td><td>让项目能互相引用、共享依赖</td><td>需要</td></tr><tr><td>根 package.json</td><td>仓库总控</td><td>公共工具 + 统一脚本</td><td>需要</td></tr><tr><td>子包 package.json</td><td>每个项目的身份证</td><td>起名、声明依赖、定义入口和脚本</td><td>需要</td></tr><tr><td>pnpm-workspace.yaml</td><td>Workspace 的声明文件（pnpm）</td><td>告诉 pnpm 哪些目录是工作区成员</td><td>使用 pnpm 时需要</td></tr></tbody></table><p>再看它们之间的关系：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根目录 package.json          ← 管理者</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ 通过 Workspace 机制连接</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>   ┌────┴────┐</span></span>
<span class="line"><span>   │         │</span></span>
<span class="line"><span>apps/web   packages/ui       ← 被管理者（各自有身份证）</span></span>
<span class="line"><span>   │         │</span></span>
<span class="line"><span>   └────┬────┘</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>   通过 workspace:* 互相引用</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="第七章-总结" tabindex="-1">第七章：总结 <a class="header-anchor" href="#第七章-总结" aria-label="Permalink to &quot;第七章：总结&quot;">​</a></h2><ol><li><strong>Monorepo</strong> 解决的是「代码放哪里」的问题，它只是一种组织方式。</li><li><strong>Workspace</strong> 解决的是「放在一起之后怎么互相用」的问题，需要配置文件支持。</li><li>根目录和子包的 <code>package.json</code> 职责不同，都是必需的。</li><li>子包不会去「引入」根目录的 <code>package.json</code>，包管理器通过 Workspace 自动连接它们。</li><li>没有 Workspace 的 Monorepo，只是文件夹的集合；有了 Workspace，才真正发挥协作价值。</li></ol><p>理解这几层区别后，再去看 Turborepo、Changesets、Nx 等工具，就会清晰很多。</p>`,61))])}const q=n(c,[["render",d]]);export{f as __pageData,q as default};
